/* @autogenerated */
package net.civeira.phylax.feature.observe.source;

import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.common.security.SecureTokenService;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceChangeSet;
import net.civeira.phylax.feature.observe.observedsource.domain.gateway.ObservedSourceCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedsource.domain.gateway.ObservedSourceFilter;

/**
 * Keeps observed-source in sync with the entities the origins come from.
 *
 * <ul>
 * <li>Create: a managed source with a random ingest key, enabled if
 * {@code app.observe.auto-enable}.</li>
 * <li>Update: only the copied values (code, name, origin-enabled) are overwritten; the
 * configuration of the observability (sampling, retention...) is kept.</li>
 * <li>Delete: the source is marked as detached, never deleted, so its data are still visible.</li>
 * </ul>
 * The listeners generated by the trait call it inside the transaction of the change; the startup
 * reconciles every origin.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class ObservedSourceSyncService {

  public static final String SELF = "self";
  /** Explicit defaults: the default of the model is not applied when the row is created. */
  static final String DEFAULT_LEVEL = "INFO";
  static final int DEFAULT_SAMPLE_RATE = 100;

  private final ObservedSourceCommandRepositoryGateway sources;
  private final SecureTokenService tokens;
  private final SourceRegistry registry;
  private final @ConfigProperty(name = "app.observe.auto-enable",
      defaultValue = "true") boolean autoEnable;

  public void upsert(final OriginRef origin) {
    Optional<ObservedSource> current = findByOrigin(origin.type(), origin.ref());
    if (current.isPresent()) {
      ObservedSource existing = current.get();
      if (!Boolean.TRUE.equals(existing.isManaged())) {
        return;
      }
      ObservedSourceChangeSet change = new ObservedSourceChangeSet()
          .code(uniqueCode(origin.code(), origin.type(), existing.getUid()))
          .originEnabled(origin.enabled()).detached(false);
      if (null != origin.name()) {
        change.name(origin.name());
      }
      sources.update(existing, existing.update(change));
    } else {
      ObservedSourceChangeSet change =
          new ObservedSourceChangeSet().newUid().originType(origin.type()).originRef(origin.ref())
              .managed(true).code(uniqueCode(origin.code(), origin.type(), null))
              .originEnabled(origin.enabled()).detached(false).ingestKey(newIngestKey())
              .minLevel(DEFAULT_LEVEL).traceSampleRate(DEFAULT_SAMPLE_RATE);
      if (null != origin.name()) {
        change.name(origin.name());
      }
      ObservedSource created = ObservedSource.create(change);
      sources.create(autoEnable ? created.enable() : created);
    }
    registry.invalidate();
  }

  public void detach(final String type, final String ref) {
    findByOrigin(type, ref).ifPresent(existing -> {
      sources.update(existing,
          existing.update(new ObservedSourceChangeSet().detached(true).originEnabled(false)));
      registry.invalidate();
    });
  }

  /**
   * Creates the source of the application itself if it does not exist.
   */
  @Transactional
  public void ensureSelf(final String code) {
    if (!sources.list(ObservedSourceFilter.builder().originType(SELF).build()).isEmpty()) {
      return;
    }
    ObservedSourceChangeSet change =
        new ObservedSourceChangeSet().newUid().originType(SELF).managed(false)
            .code(uniqueCode(code, SELF, null)).name(code).originEnabled(true).detached(false)
            .ingestKey(newIngestKey()).minLevel(DEFAULT_LEVEL).traceSampleRate(DEFAULT_SAMPLE_RATE);
    sources.create(ObservedSource.create(change).enable());
    registry.invalidate();
  }

  /**
   * Upserts every origin of the readers and detaches the managed sources whose row no longer
   * exists.
   */
  @Transactional
  public void reconcile(final List<ObservedOriginReader> readers) {
    for (ObservedOriginReader reader : readers) {
      Set<String> present = new HashSet<>();
      for (OriginRef origin : reader.readAll()) {
        upsert(origin);
        present.add(origin.ref());
      }
      for (ObservedSource source : sources
          .list(ObservedSourceFilter.builder().originType(reader.originType()).build())) {
        boolean orphan =
            Boolean.TRUE.equals(source.isManaged()) && !Boolean.TRUE.equals(source.isDetached())
                && source.getOriginRef().map(ref -> !present.contains(ref)).orElse(false);
        if (orphan) {
          detach(reader.originType(), source.getOriginRef().get());
        }
      }
    }
    log.info("Observed sources reconciled with {} origin readers", readers.size());
  }

  /** Assigns a known ingest key to a source (seeds, deploys with fixed keys). */
  public void assignIngestKey(final String code, final String key) {
    sources.find(ObservedSourceFilter.builder().code(code).build()).ifPresent(existing -> {
      sources.update(existing, existing.update(new ObservedSourceChangeSet().ingestKey(key)));
      registry.invalidate();
    });
  }

  private Optional<ObservedSource> findByOrigin(final String type, final String ref) {
    if (null == ref) {
      return Optional.empty();
    }
    return sources.list(ObservedSourceFilter.builder().originType(type).originRef(ref).build())
        .stream().findFirst();
  }

  /** The code is unique: an app and an api with the same code get the type as suffix. */
  private String uniqueCode(final String code, final String type, final String ownUid) {
    String base = null == code || code.isBlank() ? type : code;
    Optional<ObservedSource> other = sources.find(ObservedSourceFilter.builder().code(base).build())
        .filter(found -> !found.getUid().equals(ownUid));
    return other.isPresent() ? base + "-" + type : base;
  }

  private String newIngestKey() {
    return "obs_" + tokens.generate();
  }
}
